// The data page's numbers (/best-football-squares-numbers), worked out from
// scripts/seo/data/nflFinals.ts (generated by scripts/seo/stats.ts), and the
// CSV download build.ts publishes next to it. Pure.

import { DIGIT_SHARE, FIRST_SEASON, GAMES, HITS, LAST_SEASON, SEASONS, TOP_FINALS } from "./data/nflFinals.ts";

export { DIGIT_SHARE, FIRST_SEASON, GAMES, LAST_SEASON, SEASONS, TOP_FINALS };

/** Chance (%) that one square, the x and y digits, hits on the final score. */
export const squarePct = (x: number, y: number): number => (100 * HITS[x][y]) / GAMES;

/** The whole board as percentages: PCT[x][y]. */
export const PCT: number[][] = HITS.map((row, x) => row.map((_, y) => squarePct(x, y)));

export interface RankedSquare {
  x: number;
  y: number;
  pct: number;
}

/** The 55 distinct squares (x <= y; a square and its mirror hit equally often), best first. */
export const RANKED: RankedSquare[] = PCT.flatMap((row, x) => row.map((pct, y) => ({ x, y, pct })).filter((s) => s.x <= s.y)).sort(
  (a, b) => b.pct - a.pct || a.x - b.x || a.y - b.y,
);

/** Digits 0-9, most common last digit of a team's final score first. */
export const DIGITS_BY_SHARE = DIGIT_SHARE.map((share, digit) => ({ digit, share })).sort((a, b) => b.share - a.share || a.digit - b.digit);

/** "0–7" */
export const squareName = (s: { x: number; y: number }): string => `${s.x}–${s.y}`;

/** "3.6%", or two decimals under 1% ("0.05%"). */
export const fmtPct = (pct: number): string => `${pct < 1 ? pct.toFixed(2) : pct.toFixed(1)}%`;

/** About 1 game in N. */
export const oneIn = (pct: number): number => Math.round(100 / pct);

export const fmtCount = (n: number): string => n.toLocaleString("en-US");

/** "0, 7, 4 and 3" */
export function listOf(items: (string | number)[]): string {
  const s = items.map(String);
  return s.length <= 1 ? (s[0] ?? "") : `${s.slice(0, -1).join(", ")} and ${s[s.length - 1]}`;
}

/** Share (%) of final scores landing on a square built from two of these digits. */
export function shareOf(digits: number[]): number {
  let hits = 0;
  for (const x of digits) for (const y of digits) hits += HITS[x][y];
  return (100 * hits) / GAMES;
}

/** The CSV download: every square, one row each. */
export function finalsCsv(): string {
  const rows = ["top_digit,side_digit,share_of_final_scores_pct,games_averaged_over_both_orientations"];
  for (let x = 0; x < 10; x++) for (let y = 0; y < 10; y++) rows.push(`${x},${y},${squarePct(x, y).toFixed(3)},${HITS[x][y]}`);
  return `${rows.join("\n")}\n`;
}
